class Solution {
public:
    long long maximumProduct(vector<int>& nums, int m) {
        int n = nums.size();
        vector<long long> smx(n), smn(n);
        smx[n-1] = smn[n-1] = nums[n-1];
        for (int i = n - 2; i >= 0; i--) {
            smx[i] = max(smx[i+1], (long long)nums[i]);
            smn[i] = min(smn[i+1], (long long)nums[i]);
        }
        long long ans = LLONG_MIN;
        for (int i = 0; i + m - 1 < n; i++) {
            int j = i + m - 1;
            long long v = nums[i] >= 0 ? (long long)nums[i] * smx[j] : (long long)nums[i] * smn[j];
            ans = max(ans, v);
        }
        return ans;
    }
};

